-- Team APP multi-sport production schema foundation (PostgreSQL / Neon compatible)
-- Shared tables use sport-neutral concepts (periods, units, sequences, positions).
-- Sport-specific tracking belongs in explicitly named extension tables.

create extension if not exists pgcrypto;
create extension if not exists citext;

create type organization_role as enum ('owner','admin','coach','assistant_coach','manager','guardian','member','readonly');
create type athlete_status as enum ('active','inactive','archived');
create type attendance_status as enum ('yes','no','maybe','unknown');
create type event_type as enum ('practice','game','meeting','tournament','other');
create type visibility_scope as enum ('coaches','team','guardians','private');

create table organizations (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table users (
  id uuid primary key default gen_random_uuid(),
  auth_subject text not null unique,
  email citext unique,
  display_name text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table organization_memberships (
  organization_id uuid not null references organizations(id) on delete cascade,
  user_id uuid not null references users(id) on delete cascade,
  role organization_role not null,
  created_at timestamptz not null default now(),
  primary key (organization_id, user_id)
);

create table sports (
  id uuid primary key default gen_random_uuid(),
  code text not null unique,
  name text not null,
  config jsonb not null default '{}'::jsonb
);

create table sport_positions (
  sport_id uuid not null references sports(id) on delete cascade,
  unit_key text not null default 'default',
  code text not null,
  name text not null,
  group_code text,
  sort_order int not null default 0,
  surface_x numeric(5,2) check (surface_x between 0 and 100),
  surface_y numeric(5,2) check (surface_y between 0 and 100),
  metadata jsonb not null default '{}'::jsonb,
  primary key(sport_id, unit_key, code)
);

create table sport_layouts (
  sport_id uuid not null references sports(id) on delete cascade,
  unit_key text not null default 'default',
  code text not null,
  name text not null,
  slots jsonb not null default '[]'::jsonb,
  is_default boolean not null default false,
  metadata jsonb not null default '{}'::jsonb,
  primary key(sport_id, unit_key, code)
);

create table seasons (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references organizations(id) on delete cascade,
  sport_id uuid not null references sports(id),
  name text not null,
  starts_on date,
  ends_on date,
  created_at timestamptz not null default now()
);

create table rule_sets (
  id uuid primary key default gen_random_uuid(),
  sport_id uuid not null references sports(id),
  governing_body text not null,
  division text,
  season_year int,
  version text,
  source_url text,
  config jsonb not null default '{}'::jsonb,
  unique (sport_id, governing_body, division, season_year, version)
);


create table competition_profiles (
  id uuid primary key default gen_random_uuid(),
  sport_id uuid not null references sports(id) on delete cascade,
  profile_key text not null,
  league_key text not null,
  league_name text not null,
  governing_body text not null,
  division text,
  age_label text,
  season_year int,
  source_url text,
  age_source_url text,
  config jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique(sport_id, profile_key)
);

