-- END GENERATED COMPETITION PROFILES

create table leagues (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references organizations(id) on delete cascade,
  sport_id uuid not null references sports(id),
  name text not null,
  governing_body text,
  city text,
  state_code text,
  website_url text,
  rule_source_url text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table teams (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references organizations(id) on delete cascade,
  season_id uuid not null references seasons(id) on delete cascade,
  rule_set_id uuid references rule_sets(id),
  league_id uuid references leagues(id) on delete set null,
  competition_profile_id uuid references competition_profiles(id) on delete set null,
  name text not null,
  short_name text,
  age_group text,
  division text,
  governing_body text,
  rule_source_url text,
  local_rules_note text,
  local_rule_details jsonb not null default '{}'::jsonb,
  home_location jsonb not null default '{}'::jsonb,
  branding jsonb not null default '{}'::jsonb,
  color text,
  default_layouts jsonb not null default '{}'::jsonb,
  league_key text,
  league_name text,
  competition_profile_key text,
  rule_label text,
  rule_source_note text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table team_memberships (
  team_id uuid not null references teams(id) on delete cascade,
  user_id uuid not null references users(id) on delete cascade,
  role organization_role not null,
  created_at timestamptz not null default now(),
  primary key (team_id, user_id)
);

create table team_staff_contacts (
  id uuid primary key default gen_random_uuid(),
  team_id uuid not null references teams(id) on delete cascade,
  user_id uuid references users(id) on delete set null,
  name text not null,
  role organization_role not null default 'assistant_coach',
  email citext,
  phone text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table team_documents (
  id uuid primary key default gen_random_uuid(),
  team_id uuid not null references teams(id) on delete cascade,
  uploaded_by uuid references users(id),
  name text not null,
  content_type text,
  byte_size bigint not null default 0 check (byte_size >= 0),
  category text not null default 'General',
  visibility visibility_scope not null default 'team',
  storage_key text not null unique,
  description text,
  sha256 text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table athlete_profiles (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references organizations(id) on delete cascade,
  first_name text not null,
  last_name text not null,
  preferred_name text,
  status athlete_status not null default 'active',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table guardian_relationships (
  athlete_id uuid not null references athlete_profiles(id) on delete cascade,
  guardian_user_id uuid not null references users(id) on delete cascade,
  relationship_label text,
  is_primary boolean not null default false,
  may_receive_messages boolean not null default true,
  may_update_availability boolean not null default true,
  may_complete_forms boolean not null default true,
  created_at timestamptz not null default now(),
  primary key (athlete_id, guardian_user_id)
);

create table roster_memberships (
  id uuid primary key default gen_random_uuid(),
  team_id uuid not null references teams(id) on delete cascade,
  athlete_id uuid not null references athlete_profiles(id) on delete cascade,
  jersey_number text,
  primary_position text,
  secondary_positions text[] not null default '{}',
  sport_attributes jsonb not null default '{}'::jsonb,
  status athlete_status not null default 'active',
  coach_notes_encrypted bytea,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique(team_id, athlete_id)
);

create table venues (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references organizations(id) on delete cascade,
  name text not null,
  address text,
  latitude double precision,
  longitude double precision,
  created_at timestamptz not null default now()
);

create table playing_areas (
  id uuid primary key default gen_random_uuid(),
  venue_id uuid not null references venues(id) on delete cascade,
  name text not null,
  sport_code text,
  metadata jsonb not null default '{}'::jsonb
);

create table events (
  id uuid primary key default gen_random_uuid(),
  team_id uuid not null references teams(id) on delete cascade,
  playing_area_id uuid references playing_areas(id),
  event_type event_type not null,
  title text not null,
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  outdoor boolean not null default true,
  notes text,
  created_by uuid references users(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table attendance (
  event_id uuid not null references events(id) on delete cascade,
  athlete_id uuid not null references athlete_profiles(id) on delete cascade,
  status attendance_status not null default 'unknown',
  response_by uuid references users(id),
  note text,
  updated_at timestamptz not null default now(),
  primary key(event_id, athlete_id)
);

create table weather_snapshots (
  id uuid primary key default gen_random_uuid(),
  event_id uuid not null references events(id) on delete cascade,
  provider text not null,
  forecast_generated_at timestamptz,
  fetched_at timestamptz not null default now(),
  summary jsonb not null,
  hourly jsonb not null default '[]'::jsonb
);

create table weather_alerts (
  id uuid primary key default gen_random_uuid(),
  event_id uuid not null references events(id) on delete cascade,
  provider_alert_id text not null,
  severity text,
  headline text,
  starts_at timestamptz,
  ends_at timestamptz,
  payload jsonb not null,
  created_at timestamptz not null default now(),
  unique(event_id, provider_alert_id)
);

create table lineups (
  id uuid primary key default gen_random_uuid(),
  team_id uuid not null references teams(id) on delete cascade,
  event_id uuid references events(id) on delete cascade,
  name text not null,
  status text not null default 'draft',
  created_by uuid references users(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table lineup_periods (
  id uuid primary key default gen_random_uuid(),
  lineup_id uuid not null references lineups(id) on delete cascade,
  period_number int not null check (period_number > 0),
  unit_key text not null default 'default',
  layout_key text not null default 'standard',
  unique(lineup_id, period_number, unit_key)
);

create table position_assignments (
  lineup_period_id uuid not null references lineup_periods(id) on delete cascade,
  athlete_id uuid not null references athlete_profiles(id) on delete cascade,
  slot_key text not null,
  role_code text not null,
  primary key(lineup_period_id, slot_key),
  unique(lineup_period_id, athlete_id)
);

create table lineup_sequences (
  lineup_id uuid not null references lineups(id) on delete cascade,
  sequence_kind text not null,
  athlete_id uuid not null references athlete_profiles(id) on delete cascade,
  sequence_slot int not null check (sequence_slot > 0),
  metadata jsonb not null default '{}'::jsonb,
  primary key(lineup_id, sequence_kind, sequence_slot),
  unique(lineup_id, sequence_kind, athlete_id)
);


create table baseball_pitching_appearances (
  id uuid primary key default gen_random_uuid(),
  event_id uuid not null references events(id) on delete cascade,
  athlete_id uuid not null references athlete_profiles(id) on delete cascade,
  pitches int not null default 0 check (pitches >= 0),
  innings_outs int not null default 0 check (innings_outs >= 0),
  started_at timestamptz,
  ended_at timestamptz,
  created_at timestamptz not null default now()
);

create table lineup_presets (
  id uuid primary key default gen_random_uuid(),
  team_id uuid not null references teams(id) on delete cascade,
  name text not null,
  unit_key text not null default 'default',
  layout_key text not null default 'standard',
  assignments jsonb not null default '{}'::jsonb,
  created_by uuid references users(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique(team_id, unit_key, name)
);

create table game_sessions (
  id uuid primary key default gen_random_uuid(),
  event_id uuid not null unique references events(id) on delete cascade,
  lineup_id uuid references lineups(id) on delete set null,
  status text not null default 'ready' check (status in ('ready','active','ended')),
  current_period int not null default 1 check (current_period > 0),
  current_unit_key text not null default 'default',
  side_label text,
  score_for int not null default 0 check (score_for >= 0),
  score_against int not null default 0 check (score_against >= 0),
  sequence_index int not null default 0 check (sequence_index >= 0),
  sport_state jsonb not null default '{}'::jsonb,
  started_at timestamptz,
  ended_at timestamptz,
  created_by uuid references users(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table game_period_scores (
  game_session_id uuid not null references game_sessions(id) on delete cascade,
  period_number int not null check (period_number > 0),
  score_for int not null default 0 check (score_for >= 0),
  score_against int not null default 0 check (score_against >= 0),
  side_label text,
  metadata jsonb not null default '{}'::jsonb,
  primary key(game_session_id, period_number)
);

create table game_checkins (
  game_session_id uuid not null references game_sessions(id) on delete cascade,
  athlete_id uuid not null references athlete_profiles(id) on delete cascade,
  status text not null default 'pending' check (status in ('present','out','pending')),
  updated_by uuid references users(id),
  updated_at timestamptz not null default now(),
  primary key(game_session_id, athlete_id)
);

create table baseball_game_pitch_counts (
  game_session_id uuid not null references game_sessions(id) on delete cascade,
  period_number int not null check (period_number > 0),
  athlete_id uuid not null references athlete_profiles(id) on delete cascade,
  pitches int not null default 0 check (pitches >= 0),
  updated_at timestamptz not null default now(),
  primary key(game_session_id, period_number, athlete_id)
);

create table game_substitutions (
  id uuid primary key default gen_random_uuid(),
  game_session_id uuid not null references game_sessions(id) on delete cascade,
  period_number int not null check (period_number > 0),
  unit_key text not null default 'default',
  layout_key text not null default 'standard',
  slot_key text not null,
  role_code text not null,
  from_athlete_id uuid references athlete_profiles(id) on delete set null,
  to_athlete_id uuid references athlete_profiles(id) on delete set null,
  created_by uuid references users(id),
  created_at timestamptz not null default now()
);

create table practice_plans (
  id uuid primary key default gen_random_uuid(),
  team_id uuid not null references teams(id) on delete cascade,
  event_id uuid references events(id) on delete set null,
  title text not null,
  created_by uuid references users(id),
  created_at timestamptz not null default now()
);

create table practice_activities (
  id uuid primary key default gen_random_uuid(),
  practice_plan_id uuid not null references practice_plans(id) on delete cascade,
  sort_order int not null,
  minutes int not null check (minutes > 0),
  title text not null,
  category text,
  notes text,
  metadata jsonb not null default '{}'::jsonb,
  unique(practice_plan_id, sort_order)
);

create table skills (
  id uuid primary key default gen_random_uuid(),
  sport_id uuid not null references sports(id),
  code text not null,
  name text not null,
  description text,
  unique(sport_id, code)
);

create table athlete_skill_notes (
  id uuid primary key default gen_random_uuid(),
  roster_membership_id uuid not null references roster_memberships(id) on delete cascade,
  skill_id uuid not null references skills(id),
  level smallint check (level between 1 and 5),
  stage text check (stage is null or stage in ('learning','developing','consistent')),
  note_encrypted bytea,
  visibility visibility_scope not null default 'coaches',
  created_by uuid references users(id),
  created_at timestamptz not null default now()
);

create table athlete_development_goals (
  id uuid primary key default gen_random_uuid(),
  roster_membership_id uuid not null references roster_memberships(id) on delete cascade,
  goal_text_encrypted bytea not null,
  status text not null default 'active' check (status in ('active','completed','archived')),
  visibility visibility_scope not null default 'coaches',
  created_by uuid references users(id),
  created_at timestamptz not null default now(),
  completed_at timestamptz
);

create table lessons (
  id uuid primary key default gen_random_uuid(),
  sport_id uuid not null references sports(id),
  rule_set_id uuid references rule_sets(id),
  slug text not null,
  title text not null,
  body jsonb not null,
  source_refs jsonb not null default '[]'::jsonb,
  published boolean not null default false,
  unique(sport_id, slug, rule_set_id)
);

create table conversations (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references organizations(id) on delete cascade,
  team_id uuid references teams(id) on delete cascade,
  kind text not null,
  name text,
  visibility visibility_scope not null default 'team',
  created_at timestamptz not null default now()
);

create table conversation_members (
  conversation_id uuid not null references conversations(id) on delete cascade,
  user_id uuid not null references users(id) on delete cascade,
  joined_at timestamptz not null default now(),
  primary key(conversation_id, user_id)
);

-- Ciphertext only for E2EE conversations. The server should not receive plaintext message bodies.
create table messages (
  id uuid primary key default gen_random_uuid(),
  conversation_id uuid not null references conversations(id) on delete cascade,
  sender_user_id uuid not null references users(id),
  ciphertext bytea not null,
  nonce bytea not null,
  crypto_version text not null,
  client_message_id text not null,
  sent_at timestamptz not null default now(),
  edited_at timestamptz,
  deleted_at timestamptz,
  unique(sender_user_id, client_message_id)
);

create table audit_events (
  id bigserial primary key,
  organization_id uuid not null references organizations(id) on delete cascade,
  actor_user_id uuid references users(id),
  action text not null,
  entity_type text not null,
  entity_id text,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create index idx_roster_team on roster_memberships(team_id) where status='active';
create index idx_events_team_time on events(team_id, starts_at);
create index idx_weather_event_time on weather_snapshots(event_id, fetched_at desc);
create index idx_lineups_team on lineups(team_id, created_at desc);
create index idx_messages_conversation_time on messages(conversation_id, sent_at desc);
create index idx_audit_org_time on audit_events(organization_id, created_at desc);

